export const getGetDarkAceDailyFairnessUrl = (params: GetDarkAceDailyFairnessParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/dark-ace/fairness/daily?${stringifiedParams}` : `/api/dark-ace/fairness/daily`
}

